   \end{array}\right)=\sigma h  \left(\begin{array}{c}
   \varphi_0'+h p_1  \\ h p_2
   \end{array}\right).
   \end{equation}
   In other words,
   \begin{equation} \left(\begin{array}{cc}
   L_+ - 12 h \varphi_0 (a_0 \Psi_1^0+b_0 \Psi_2^0) & O(h)  \\
